+func TestWriteFailureRouteCodes(t *testing.T) {
+	cases := []struct {
+		code   ErrorCode
+		status string
+	}{
+		{CodeRouteDown, "502 Bad Gateway"},
+		{CodeRouteRefused, "502 Bad Gateway"},
+		{CodeRouteTimeout, "504 Gateway Timeout"},
